    if((m=value.match(/^(Выполнить задачу|Вернуть задачу|Изменить):\s*(.*)$/)))return ({ky:m[1]==='Выполнить задачу'?'Тапшырманы аткаруу: ':m[1]==='Вернуть задачу'?'Тапшырманы кайтаруу: ':'Өзгөртүү: ',uz:m[1]==='Выполнить задачу'?'Vazifani bajarish: ':m[1]==='Вернуть задачу'?'Vazifani qaytarish: ':'Oʻzgartirish: ',tg:m[1]==='Выполнить задачу'?'Иҷрои вазифа: ':m[1]==='Вернуть задачу'?'Баргардондани вазифа: ':'Тағйир додан: '})[code]+m[2];
