    if((m=value.match(/^(.+), Россия$/)))return t(m[1])+({ky:', Россия',uz:', Rossiya',tg:', Русия'})[code];
    if((m=value.match(/^(\d+) возможностей$/)))return ({ky:m[1]+' мүмкүнчүлүк',uz:m[1]+' imkoniyat',tg:m[1]+' имконият'})[code];
    if((m=value.match(/^(\d+) из (\d+) задач выполнено$/)))return ({ky:m[2]+' тапшырманын '+m[1]+' аткарылды',uz:m[2]+' vazifadan '+m[1]+' tasi bajarildi',tg:m[2]+' вазифа, аз онҳо '+m[1]+' иҷро шуд'})[code];
